// router/guards.ts
import type { Router } from 'vue-router';
import { useAuthStore } from '@/stores/auth';

export function setupNavigationGuards(router: Router) {
  router.beforeEach(async (to, from) => {
    const authStore = useAuthStore();

    // Kiểm tra route meta xem trang có yêu cầu xác thực không
    if (to.meta.requiresAuth && !authStore.isAuthenticated) {
      // Redirect về Login kèm theo query redirect để quay lại sau
      return {
        path: '/login',
        query: { redirect: to.fullPath }
      };
    }

    // Kiểm tra phân quyền Admin
    if (to.meta.requiresAdmin && authStore.userRole !== 'ADMIN') {
      return { path: '/403-forbidden' };
    }

    // Trả về true hoặc undefined để cho phép chuyển tiếp an toàn
    return true;
  });
}

