import { createRouter, createWebHistory, type RouterScrollBehavior } from 'vue-router';

const scrollBehavior: RouterScrollBehavior = (to, from, savedPosition) => {
  // 1. Phục hồi vị trí cuộn khi người dùng dùng nút Back/Forward
  if (savedPosition) {
    return savedPosition;
  }

  // 2. Cuộn mượt tới thẻ neo nếu có hash (#comments)
  if (to.hash) {
    return {
      el: to.hash,
      behavior: 'smooth'
    };
  }

  // 3. Nếu chuyển qua lại giữa cùng component cha (sub-tab), có thể không cuộn
  if (to.meta.keepScroll) {
    return false;
  }

  // 4. Mặc định: Cuộn về đỉnh trang với hiệu ứng mượt
  return new Promise((resolve) => {
    // Chờ 300ms nếu có page transition out-in
    setTimeout(() => {
      resolve({ left: 0, top: 0, behavior: 'smooth' });
    }, 300);
  });
};

export const router = createRouter({
  history: createWebHistory(),
  routes: [],
  scrollBehavior
});

// composables/useNotificationContext.ts
import { provide, inject, type InjectionKey } from 'vue';

export interface NotificationContext {
  showSuccess: (message: string) => void;
  showError: (message: string) => void;
}

// 1. Tạo InjectionKey duy nhất bằng Symbol
export const NotificationKey: InjectionKey<NotificationContext> = Symbol('NotificationKey');

// 2. Provider helper để component cha dùng gọn gàng
export function provideNotification(context: NotificationContext) {
  provide(NotificationKey, context);
}

// 3. Consumer helper: Tự động check context tồn tại và trả về non-null type
export function useNotification(): NotificationContext {
  const context = inject(NotificationKey);
  if (!context) {
    throw new Error('useNotification phải được sử dụng bên trong component có provide NotificationContext!');
  }
  return context;
}

