// stores/useAuthStore.ts - Setup Store kèm pattern tự tạo $reset
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import { useRouter } from 'vue-router';

export const useAuthStore = defineStore('auth', () => {
  const router = useRouter(); // Dùng được router trực tiếp trong Setup Store

  const token = ref<string | null>(null);
  const user = ref<{ name: string; role: string } | null>(null);

  const isAuthenticated = computed(() => token.value !== null);

  // Khắc phục hạn chế thiếu $reset() bằng cách tự viết action reset
  function reset(): void {
    token.value = null;
    user.value = null;
  }

  async function logout(): Promise<void> {
    reset();
    await router.push('/login');
  }

  return { token, user, isAuthenticated, reset, logout };
});

// plugins/piniaCustomPersist.ts - Viết custom persist plugin tối giản, an toàn
import type { PiniaPluginContext } from 'pinia';

export function customPersistPlugin(context: PiniaPluginContext) {
  const { store } = context;
  const storageKey = `app_store_${store.$id}`;

  // 1. Phục hồi state an toàn khi khởi động (chỉ chạy ở phía client)
  if (typeof window !== 'undefined') {
    try {
      const savedState = localStorage.getItem(storageKey);
      if (savedState) {
        store.$patch(JSON.parse(savedState));
      }
    } catch (e) {
      console.warn(`Lỗi phục hồi state cho store ${store.$id}:`, e);
    }
  }

  // 2. Tự động subscribe và lưu lại mỗi khi state thay đổi
  store.$subscribe((_mutation, state) => {
    if (typeof window !== 'undefined') {
      try {
        localStorage.setItem(storageKey, JSON.stringify(state));
      } catch (err) {
        console.error('Không thể lưu state vào localStorage (có thể bị đầy quota):', err);
      }
    }
  });
}

// directives/vClickOutside.ts
import type { Directive, DirectiveBinding } from 'vue';

type Handler = (event: MouseEvent) => void;
const handlerMap = new WeakMap<HTMLElement, (e: MouseEvent) => void>();

export const vClickOutside: Directive<HTMLElement, Handler> = {
  mounted(el: HTMLElement, binding: DirectiveBinding<Handler>) {
    const onDocClick = (event: MouseEvent) => {
      const target = event.target as Node;
      // Nếu click ra ngoài el và nội dung bên trong el
      if (el && !el.contains(target)) {
        binding.value(event);
      }
    };

    // Lưu handler vào WeakMap để tháo gỡ khi unmount
    handlerMap.set(el, onDocClick);
    document.addEventListener('click', onDocClick, true);
  },

  unmounted(el: HTMLElement) {
    const handler = handlerMap.get(el);
    if (handler) {
      document.removeEventListener('click', handler, true);
      handlerMap.delete(el);
    }
  }
};

