// server/render-sample.ts - Mô phỏng cơ chế cốt lõi của Vue SSR
import { createSSRApp } from 'vue';
import { renderToString } from 'vue/server-renderer';

// Factory function tạo app instance độc lập cho MỖI request
export function createApp(initialData: Record<string, any>) {
  const app = createSSRApp({
    data: () => initialData,
    template: `<div><h1>{{ title }}</h1><p>View count: {{ views }}</p></div>`
  });
  return app;
}

// Xử lý request từ client
export async function handleRequest(req: any) {
  const initialData = { title: 'Bài viết SSR', views: 1500 };
  const app = createApp(initialData);

  // Chuyển component thành HTML string
  const htmlContent = await renderToString(app);

  return `
    <!DOCTYPE html>
    <html>
      <body>
        <div id="app">${htmlContent}</div>
        <script>window.__INITIAL_STATE__ = ${JSON.stringify(initialData)}</script>
        <script src="/client-bundle.js"></script>
      </body>
    </html>
  `;
}

