// plugins/piniaActionProfiler.ts
import type { PiniaPluginContext } from 'pinia';

// Mở rộng kiểu TypeScript cho toàn bộ store
declare module 'pinia' {
  export interface PiniaCustomProperties {
    profilerEnabled: boolean;
  }
}

export function piniaActionProfilerPlugin({ store }: PiniaPluginContext) {
  // Lắng nghe và đo lường mọi action trong store
  store.$onAction(({ name, args, after, onError }) => {
    const startTime = performance.now();
    console.log(`[Action Started] ${store.$id}.${name} với tham số:`, args);

    after((result) => {
      const duration = performance.now() - startTime;
      if (duration > 500) {
        console.warn(`[SLOW ACTION] ${store.$id}.${name} mất ${duration.toFixed(2)}ms!`);
      }
    });

    onError((error) => {
      console.error(`[ACTION ERROR] ${store.$id}.${name} thất bại:`, error);
    });
  });

  // Gắn thêm thuộc tính toàn cục cho mọi store
  return { profilerEnabled: true };
}

